@dataclass
class Account:
    floor: int
    balance: int = 0

    def __post_init__(self) -> None:
        assert self.balance >= self.floor, f"balance {self.balance} < floor {self.floor}"

    def withdraw(self, amount: int) -> None:
        if amount <= 0:
            raise ValueError(f"amount must be positive: {amount}")
        next_balance = self.balance - amount
        if next_balance < self.floor:
            raise ValueError("withdrawal would break the invariant")
        self.balance = next_balance
        assert self.balance >= self.floor, f"invariant: {self.balance} < {self.floor}"

